ROWS = [{'anomaly_id': 'initial_rate_window', 'name': 'Initial rate and enzyme time courses', 'description': 'Estimate an initial rate from measured early time-course linearity, with substrate depletion controlled. A single endpoint cannot establish initial linearity. Select observation times and enzyme amount from evidence; do not assume an unseen early interval is linear.', 'evidence_required': ['A time course and appropriate blank; check the assay chemistry and measurement conditions'], 'provenance': ASSAY}, {'anomaly_id': 'kinetic_parameter_identifiability', 'name': 'Michaelis-Menten parameter coverage', 'description': 'Substrate levels must provide informative rate coverage to identify both KM and Vmax. Fit uncertainty and the measured concentration range matter in addition to fit agreement. kcat additionally depends on the enzyme concentration basis; nominal protein concentration is not proof of active-site concentration.', 'evidence_required': ['Initial rates across known substrate levels; explicit enzyme concentration basis'], 'provenance': ASSAY}, {'anomaly_id': 'camera_clipping', 'name': 'Camera clipping and absorbance conversion', 'description': 'Pixels at the instrument boundary carry a censored signal. Blank and dark correction, exposure, quantization and optical path affect inferred absorbance. A clipped reading does not quantify the underlying signal or identify its cause. Interpret measurements within the characterized detector response.', 'evidence_required': ['Camera pixels, supplied calibration and exposure; apply to the recorded sensor channel'], 'provenance': 'authored:camera-measurement-model', 'source_kind': 'engineering guidance'}, {'anomaly_id': 'replicate_disagreement', 'name': 'Replicate comparison and outlier uncertainty', 'description': 'Compare replicates prepared and observed under comparable conditions. A discordant observation warrants inspection of acquisition, preparation and timing records. A cause is not established by disagreement alone, and excluding a point must have an evidence-based rationale.', 'evidence_required': ['Comparable independent replicates and their preparation and acquisition times'], 'provenance': 'authored:measurement-quality-guidance'}, {'anomaly_id': 'handling_resolution', 'name': 'Liquid handling and timing resolution', 'description': 'Pipette operating range and precision depend on the selected instrument and volume. Choose a design compatible with the available equipment. Compare the useful observation window with dispensing and readout durations and uncertainty; modelled timing is not measured robot timing.', 'evidence_required': ['Declared instrument range and measured or explicitly assumed operation durations'], 'provenance': PIPETTES}, {'anomaly_id': 'camera_location_change', 'name': 'Camera location and preparation agreement', 'description': 'A command record describes an intended operation; an image is a separate measurement. Named observations require a stated image coordinate convention, but an optical response does not require a fully diagnosed physical command mapping to be observed. Distinguish physical delivery attribution from a local input-response hypothesis that can be tested under explicit assumptions and physical limits. An optical-only objective may not require verified composition; a user-required destination remains binding. Image changes do not alone establish reagent identity, delivered volume, repeatability or the cause of disagreement. Keep recorded actions, observations and interpretations distinct.', 'evidence_required': ['Before and after camera evidence at identified locations and a command record'], 'provenance': 'authored:camera-command-comparison'}]
